import requests


class OneClickSession(object):
    def __init__(self, ip, port, username="", password="", secure=False, verify=False):
        self.protocol = 'https://' if secure else 'http://'
        self.ip = ip
        self.port = port
        self.username = username
        self.password = password
        self.verify=verify
        self.base_url = '{protocol}{host}:{port}/action'.format(protocol=self.protocol,
                                                         host=self.ip,
                                                         port=self.port)

    def send_request(self,
                     method,
                     endpoint,
                     **options):

        method = getattr(requests, method)
        url = self.base_url + endpoint
        # header = self._create_header(content_type)
        options.update({'verify': self.verify})
        response = method(url, **options)
        if response.status_code != 200:
            response.raise_for_status()

        return response.json()

    def _create_header(self, content_type='application/json'):
        # access_token = self.__get_valid_access_token()
        # auth_header = {'Authorization': 'bearer {}'.format(access_token)}
        header = {}
        if content_type is not None:
            header['Content-Type'] = content_type

        return header